### Instruction:
Write a Golang program that monitors a directory for changes (file creation, modification, deletion) and logs these events to a PostgreSQL database along with timestamps and file metadata.
PLAINFORMAT

### Response:
package main

import (
	"database/sql"
	"fmt"
	"log"
	"os"
	"time"

	"github.com/fsnotify/fsnotify"
	_ "github.com/lib/pq"
)

const (
	DB_USER     = "your_db_user"
	DB_PASSWORD = "your_db_password"
	DB_NAME     = "your_db_name"
)

func main() {
	// Connect to the database
	dbinfo := fmt.Sprintf("user=%s password=%s dbname=%s sslmode=disable",
		DB_USER, DB_PASSWORD, DB_NAME)
	db, err := sql.Open("postgres", dbinfo)
	checkErr(err)
	defer db.Close()

	// Create table if not exists
	createTableQuery := `
	CREATE TABLE IF NOT EXISTS file_events (
		id SERIAL PRIMARY KEY,
		event_type TEXT NOT NULL,
		file_name TEXT NOT NULL,
		timestamp TIMESTAMP NOT NULL
	)`
	_, err = db.Exec(createTableQuery)
	checkErr(err)

	// Initialize fsnotify watcher
	watcher, err := fsnotify.NewWatcher()
	checkErr(err)
	defer watcher.Close()

	done := make(chan bool)
	go func() {
		for {
			select {
			case event := <-watcher.Events:
				log.Println("event:", event)
				if event.Op&fsnotify.Write == fsnotify.Write {
					log.Println("modified file:", event.Name)
					insertEvent(db, "MODIFY", event.Name)
				} else if event.Op&fsnotify.Create == fsnotify.Create {
					log.Println("created file:", event.Name)
					insertEvent(db, "CREATE", event.Name)
				} else if event.Op&fsnotify.Remove == fsnotify.Remove {
					log.Println("deleted file:", event.Name)
					insertEvent(db, "DELETE", event.Name)
				}
			case err := <-watcher.Errors:
				log.Println("error:", err)
			}
		}
	}()

	dirToWatch := "."
	if len(os.Args) > 1 {
		dirToWatch = os.Args[1]
	}

	err = watcher.Add(dirToWatch)
	checkErr(err)

	<-done
}

func insertEvent(db *sql.DB, eventType string, fileName string) {
	stmt, err := db.Prepare("INSERT INTO file_events(event_type, file_name, timestamp) VALUES($1, $2, $3)")
	checkErr(err)

	_, err = stmt.Exec(eventType, fileName, time.Now())
	checkErr(err)
}

func checkErr(err error) {
	if err != nil {
		log.Fatal(err)
	}
}

### Instruction:
Create a Java program that generates a random maze of a given size (rows and columns) using depth-first search algorithm, and then finds the shortest path from the top-left corner to the bottom-right corner using breadth-first search algorithm.


### Response:
Here's a Java program that generates a random maze using the depth-first search algorithm and finds the shortest path from the top-left corner to the bottom-right corner using the breadth-first search algorithm:

```java
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedList;
import java.util.List;
import java.util.Queue;
import java.util.Random;

public class MazeGenerator {
    private static final int WALL = 0;
    private static final int PATH = 1;
    private static final int VISITED = 2;
    private static final int[] DX = {-1, 0, 1, 0};
    private static final int[] DY = {0, 1, 0, -1};

    public static void main(String[] args) {
        int rows = 10;
        int columns = 10;
        int[][] maze = generateMaze(rows, columns);
        printMaze(maze);
        List<int[]> shortestPath = findShortestPath(maze);
        System.out.println("Shortest Path:");
        for (int[] point : shortestPath) {
            System.out.printf("(%d, %d)%n", point[0], point[1]);
        }
    }

    private static int[][] generateMaze(int rows, int columns) {
        int[][] maze = new int[rows][columns];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < columns; j++) {
                maze[i][j] = WALL;
            }
        }
        Random random = new Random();
        dfs(random, maze, 1, 1);
        return maze;
    }

    private static void dfs(Random random, int[][] maze, int x, int y) {
        maze[x][y] = PATH;
        List<Integer> directions = new ArrayList<>(4);
        for (int i = 0; i < 4; i++) {
            directions.add(i);
        }
        Collections.shuffle(directions, random);
        for (int direction : directions) {
            int nx = x + DX[direction] * 2;
            int ny = y + DY[direction] * 2;
            if (isValid(maze, nx, ny)) {
                maze[nx - DX[direction]][ny - DY[direction]] = PATH;
                dfs(random, maze, nx, ny);
            }
        }
    }

    private static boolean isValid(int[][] maze, int x, int y) {
        return x >= 1 && x < maze.length - 1 && y >= 1 && y < maze[x].length - 1 && maze[x][y] == WALL;
    }

    private static void printMaze(int[][] maze) {
        for (int[] row : maze) {
            for (int cell : row) {
                System.out.print(cell == WALL ? "#" : " ");
            }
            System.out.println();
        }
    }

    private static List<int[]> findShortestPath(int[][] maze) {
        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{1, 1, 0});
        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int x = current[0];
            int y = current[1];
            int distance = current[2];

            if (x == maze.length - 2 && y == maze[x].length - 2) {
                List<int[]> path = new ArrayList<>(distance + 1);
                while (current != null) {
                    path.add(0, new int[]{current[0], current[1]});
                    current = current[3] >= 0 ? maze[current[0] + DX[current[3]]][current[1] + DY[current[3]]] : null;
                }
                return path;
            }

            for (int direction = 0; direction < 4; direction++) {
                int nx = x + DX[direction];
                int ny = y + DY[direction];
                if (isValidForBfs(maze, nx, ny)) {
                    maze[nx][ny] = VISITED;
                    queue.offer(new int[]{nx, ny, distance + 1, (direction + 2) % 4});
                }
            }
        }
        return Collections.emptyList();
    }

    private static boolean isValidForBfs(int[][] maze, int x, int y) {
        return x >= 0 && x < maze.length && y >= 0 && y < maze[x].length && maze[x][y] == PATH;
    }
}
```

This program first generates a random maze using the depth-first search algorithm. Then it finds the shortest path from the top-left corner to the bottom-right corner using the breadth-first search algorithm and prints both the maze and the shortest path.

You can change the `rows` and `columns` variables in the `main` method to generate mazes of different sizes.

