// Define the TreeNode interface
interface TreeNode<T> {
  value: T;
  children: Array<TreeNode<T>>;
}

// DFS function using recursion
function depthFirstSearch<T>(node: TreeNode<T>, visit: (value: T) => void): void {
  // Visit the current node
  visit(node.value);

  // Recursively traverse the children nodes
  for (const child of node.children) {
    depthFirstSearch(child, visit);
  }
}

// Example usage:
// Create a sample tree with number values
